"""Cuaderno del estudiante, 8.º básico Lengua y Literatura, OA 24 (registro, desacuerdo y recursos de la oralidad)."""
from __future__ import annotations

from student_content_le8_c import E, L

OA24 = "LE08 OA 24"
MAT24 = "Este cuaderno, lápiz y los textos de ejemplo escritos en cada ejercicio; para practicar la voz, una persona de tu casa puede escucharte."

L(OA24, 1,
  MAT24,
  "Aprenderé a comparar textos orales y escritos, y a explicar sus diferencias según el contexto y el destinatario.",
  ["Distingo emisor y destinatario.", "Sé qué es un texto oral y uno escrito."],
  ["Los textos orales se producen y se escuchan en el momento. Tienen entonación, volumen, gestos y pausas; admiten repeticiones, vacilaciones («eh»), correcciones sobre la marcha y respuestas inmediatas del interlocutor. Los textos escritos se pueden planificar, revisar y corregir antes de enviarse; usan puntuación y signos para marcar lo que en la voz hace la entonación.",
   "Por eso, un mismo mensaje cambia según el medio. Oral: «Oye, o sea, fui al, eh, al mercado y compré, como, harta fruta». Escrito: «Fui al mercado y compré mucha fruta». El oral es más espontáneo y cercano; el escrito es más ordenado y preciso. Pero hay textos orales muy planificados (un discurso) y textos escritos casi orales (un mensaje de chat).",
   "Para comparar, fíjate en cuatro cosas: 1) el contexto (¿cara a cara o a distancia?), 2) el destinatario (¿amigo, autoridad, público?), 3) el nivel de planificación (¿improvisado o preparado?) y 4) los recursos (¿voz y gestos o puntuación y formato?). Elegir bien el medio y adecuar el texto muestra que dominas la comunicación."],
  [("texto oral", "mensaje producido y recibido con la voz, en el momento"), ("texto escrito", "mensaje producido con letras, que puede revisarse antes de enviarse"), ("entonación", "subida y bajada de la voz al hablar"), ("planificación", "preparación previa de lo que se va a decir o escribir")],
  [("Detectar rasgos orales", "¿Qué rasgos de oralidad tiene «Oye, o sea, fui al, eh, al mercado y compré, como, harta fruta»?",
    ["Veo «oye», «o sea», «eh», «como».", "Son muletillas y vacilaciones.", "También hay un registro cotidiano."],
    "Muletillas, vacilaciones y registro cotidiano"),
   ("Pasar a escrito", "Pasa a un texto escrito formal: «Oye, ¿cachai que llegué tarde porque, eh, el bus no pasaba?».",
    ["Elimino muletillas y apelaciones.", "Mantengo la información: llegué tarde, el bus no pasaba.", "Escribo: Llegué tarde porque el bus no pasaba."],
    "Llegué tarde porque el bus no pasaba.")],
  [("Creer que oral y escrito son iguales.", "Se escribe como se habla.", "Revisa y adecúa el texto al medio."),
   ("Creer que todo texto oral es informal.", "Se piensa en las conversaciones.", "Un discurso oral puede ser muy formal y preparado.")],
  ([E("¿Los gestos y la entonación son propios del texto oral o del escrito?", "Del oral", "Se producen al hablar."),
    E("¿Un texto escrito se puede corregir antes de enviarlo?", "Sí", "Permite una revisión previa."),
    E("¿Las vacilaciones como «eh» aparecen más en lo oral o en lo escrito?", "En lo oral", "Se producen al hablar sobre la marcha.")],
   [E("¿Qué rasgos orales hay en «Oye, o sea, fui al mercado, eh, y compré, como, harta fruta»?", "Muletillas y vacilaciones", "«O sea», «eh» y «como» son típicos de lo oral."),
    E("Una carta empieza «Estimada directora: Le escribo para solicitar...». ¿Qué rasgo escrito tiene?", "Planificación y tratamiento formal", "Está preparada y usa «le»."),
    E("¿Qué recursos escritos reemplazan la entonación: los signos de interrogación y exclamación o el color de la hoja?", "Los signos de interrogación y exclamación", "Marcan la intención.")],
   [E("Pasa a un texto escrito formal: «Oye, ¿cachai que llegué tarde porque, eh, el bus no pasaba?».", "Llegué tarde porque el bus no pasaba.", "Se eliminan muletillas y apelaciones."),
    E("¿A quién se dirige una carta que empieza «Estimado señor»: a un amigo cercano o a una persona con quien se guarda distancia?", "A una persona con quien se guarda distancia", "Es un saludo formal."),
    E("Pasa a oral informal: «Le informo que la reunión será mañana».", "Oye, la reunión es mañana", "Se simplifica el tratamiento.")],
   [E("¿Por qué en una conversación oral se puede ser menos preciso que en una carta?", "Porque el interlocutor puede preguntar en el momento", "La respuesta inmediata permite aclarar."),
    E("Un discurso preparado, ¿es un texto oral o escrito?", "Oral", "Se produce con la voz, aunque esté planificado.")],
   [E("¿Qué pierde un mensaje oral cuando se transcribe a escrito: la entonación y los gestos o las palabras?", "La entonación y los gestos", "No se pueden anotar."),
    E("Un chat entre amigos, ¿se parece más a un texto oral o a una carta formal?", "A un texto oral", "Usa lenguaje cotidiano y es espontáneo.")]),
  [E("Un aviso escolar escrito dice: «Se solicita a los estudiantes presentarse a las 8:00 horas». Un compañero lo repite oralmente: «Oye, hay que llegar a las ocho». ¿Qué cambió: el registro o la información?", "El registro", "La información se mantiene; cambia la forma de decirlo.")],
  [E("¿Los textos orales se producen en el momento?", "Sí", "Por eso admiten vacilaciones."),
   E("¿Un texto escrito puede planificarse y revisarse?", "Sí", "Esa es una de sus características."),
   E("¿Hay textos orales muy planificados?", "Sí", "Por ejemplo, un discurso.")],
  ("Compara estos dos textos de ejemplo. Oral (mensaje de voz): «Hola, oye, o sea, no voy a poder ir hoy porque, eh, me siento, como, mal». Escrito (correo): «Estimada profesora: Le informo que no podré asistir hoy porque no me siento bien. Atentamente, Camila». 1) Escribe tres diferencias. 2) Indica qué contexto y destinatario tiene cada uno. 3) Reescribe el mensaje oral como mensaje de chat a una amiga.",
   "Diferencias: el oral tiene muletillas y vacilaciones; el escrito es ordenado y formal; el oral usa tratamiento cercano, el escrito «Le informo». Contexto: oral, informal, a alguien cercano; escrito, formal, a una profesora. Chat: «Hola, hoy no voy porque no me siento bien».",
   ["nombra tres diferencias", "relaciona con contexto y destinatario", "adecúa un tercer texto"], ["lista de diferencias", "texto de chat"], ["escribir como se habla", "no considerar el destinatario"], "Lee el mensaje de chat en voz alta y comprueba que sea natural."),
  "Anota dos mensajes que hayas recibido hoy, uno oral y uno escrito, y compara una diferencia.",
  "Escribe un mensaje a una autoridad y otro a un amigo con la misma información.")

L(OA24, 2,
  MAT24,
  "Aprenderé a reconocer los registros formal e informal y a emplear el adecuado según la situación.",
  ["Comparo textos orales y escritos.", "Distingo destinatario y propósito."],
  ["El registro es la forma de hablar o escribir según la situación. El registro formal se usa con personas con quienes se guarda distancia o en situaciones oficiales (entrevistas, exposiciones, trámites): tratamiento de «usted», vocabulario preciso, oraciones completas, sin muletillas ni apodos. El registro informal o coloquial se usa con amigos y familia: tratamiento de «tú» o «vos», vocabulario cotidiano y expresiones como «po», «al tiro», «¿cachai?».",
   "Hay situaciones intermedias. Con un profesor se usa un registro cuidado, aunque cercano. Con un compañero de grupo en una tarea, un registro semiformal. Lo importante es leer la situación: ¿quién es el destinatario?, ¿para qué hablo?, ¿en qué lugar?, ¿qué tan cercana es la relación?",
   "Usar el registro equivocado puede ofender o confundir. Hablar a una autoridad con apodos suena irrespetuoso. Hablar a un amigo con un lenguaje muy formal suena frío o raro. Dominar los registros es saber cambiar de uno a otro según la ocasión. Para reconocer el registro, observa el tratamiento (usted o tú), el vocabulario, las muletillas y la forma de saludar y despedirse."],
  [("registro", "forma de hablar o escribir según la situación"), ("registro formal", "forma cuidada de hablar, con usted y vocabulario preciso"), ("registro informal", "forma cotidiana de hablar entre personas cercanas"), ("tratamiento", "forma de dirigirse a alguien: tú, usted")],
  [("Reconocer el registro", "¿Qué registro tiene «Buenos días, señora directora, quisiera solicitar su autorización»?",
    ["Tiene tratamiento de usted («su autorización»).", "El vocabulario es cuidado.", "Es registro formal."],
    "Formal"),
   ("Elegir el registro", "Vas a hacer una entrevista a un vecino que no conoces. ¿Qué registro usas?",
    ["No lo conozco bien.", "Es una situación de entrevista.", "Uso registro formal."],
    "Formal")],
  [("Hablar igual con todos.", "Se usa un solo registro.", "Adecúa el registro al destinatario y a la situación."),
   ("Creer que formal es hablar complicado.", "Se confunde con rebuscado.", "Formal es cuidado y claro, no difícil.")],
  ([E("¿«¿Qué onda, profe?» es registro formal o informal?", "Informal", "Es coloquial y usa «profe»."),
    E("¿«Solicito su autorización» es registro formal o informal?", "Formal", "Usa «su» y vocabulario cuidado."),
    E("¿«Al tiro» es una expresión formal o coloquial?", "Coloquial", "Es una expresión cotidiana.")],
   [E("¿Qué tratamiento corresponde al registro formal: «usted» o «tú»?", "Usted", "Marca una distancia respetuosa."),
    E("Vas a hablar con un amigo en el recreo. ¿Qué registro es adecuado?", "Informal", "Hay una relación cercana."),
    E("Vas a exponer ante tu curso y un jurado. ¿Qué registro usas: formal o muy informal?", "Formal", "La situación es oficial.")],
   [E("Elige la frase más formal: «Oye, ¿me prestai el lápiz?» o «¿Podría prestarme su lápiz, por favor?»", "¿Podría prestarme su lápiz, por favor?", "Usa «podría» y «su»."),
    E("Elige la frase informal: «Le agradezco su atención» o «Gracias, po»", "Gracias, po", "Usa la expresión «po»."),
    E("¿Qué registro tiene «Buenos días. Quisiera consultar los horarios, por favor»?", "Formal", "Es cortés y cuidado.")],
   [E("¿Por qué puede ofender hablar a una autoridad con apodos?", "Porque no muestra respeto", "El registro no coincide con la situación."),
    E("¿Por qué sonaría raro hablar a un amigo cercano con «Estimado señor»?", "Porque suena frío o demasiado formal", "El registro no coincide.")],
   [E("Una estudiante dice a su profesor: «Oye, profe, ¿me das la hoja?». ¿Qué registro usa y cuál sería más adecuado?", "Informal; sería más adecuado uno cuidado", "La situación escolar exige un registro más cuidado."),
    E("¿Dominar los registros es saber cambiar de uno a otro según la ocasión?", "Sí", "Esa es la competencia.")]),
  [E("En una entrevista de ejemplo a un bombero, un estudiante saluda: «Buenos días, señor, ¿podría contarnos cómo es su trabajo?». ¿Qué registro usa?", "Formal", "Usa «señor» y «podría».")],
  [E("¿El registro formal usa tratamiento de usted?", "Sí", "Marca una distancia respetuosa."),
   E("¿El registro informal se usa con personas cercanas?", "Sí", "Es un registro cotidiano."),
   E("¿Conviene leer la situación antes de elegir el registro?", "Sí", "Quién, para qué, dónde y qué relación.")],
  ("Lee estas cuatro situaciones de ejemplo y escribe cómo saludarías en cada una, con el registro adecuado: a) recibir a la directora en tu curso; b) saludar a un amigo en el recreo; c) iniciar tu exposición ante el curso y el jurado; d) pedir un favor a un vecino mayor. Luego explica en una frase qué cambia en cada saludo.",
   "a) «Buenos días, señora directora, bienvenida a nuestro curso». b) «Hola, ¿cómo estás?». c) «Buenos días a todos. Hoy expondré sobre...». d) «Buenos días, don/doña ___, ¿podría ayudarme con algo?». Cambia el tratamiento (usted o tú), el vocabulario y el grado de cercanía.",
   ["adecúa el saludo al contexto", "usa tratamiento correcto", "explica los cambios"], ["cuatro saludos", "una frase de explicación"], ["usar un solo registro", "confundir formal con rebuscado"], "Representa los saludos con alguien y pregúntale cuál le pareció más natural."),
  "Anota tres expresiones informales que uses y su versión formal.",
  "Escribe el mismo pedido de ayuda en dos registros distintos.")

L(OA24, 3,
  MAT24,
  "Aprenderé a adecuar el vocabulario y la estructura de un texto oral o escrito según la situación, el propósito y el destinatario.",
  ["Reconozco registros formal e informal.", "Sé estructurar un mensaje breve."],
  ["Adecuar es ajustar lo que dices y cómo lo dices a la situación. Tiene dos aspectos. El vocabulario: palabras precisas y cuidadas para situaciones formales, palabras cotidianas para las informales. La estructura: el orden de las partes del mensaje. Un mensaje formal suele tener saludo, motivo, petición o información, agradecimiento y despedida. Uno informal puede ser más libre.",
   "Por ejemplo, para pedir permiso al director: «Estimado director: Le escribo para solicitar autorización para realizar una campaña de reciclaje el viernes. Nos ayudaría a mantener limpio el colegio. Agradezco su atención. Saludos cordiales, 8.º A». Para pedírselo a tu curso, puedes decir: «Chicos, ¿les parece si hacemos una campaña de reciclaje el viernes?».",
   "Para adecuar, hazte tres preguntas: ¿quién lo recibirá?, ¿qué quiero lograr? y ¿qué registro y estructura le conviene? Luego revisa tu texto: elimina muletillas y apodos en lo formal; incluye saludo y despedida; da una razón clara. La buena adecuación hace que tu mensaje sea bien recibido y logre su propósito."],
  [("adecuar", "ajustar un texto a la situación, el propósito y el destinatario"), ("estructura", "orden de las partes de un texto"), ("petición", "acto de pedir algo"), ("cortesía", "manera amable de comunicarse")],
  [("Adecuar un pedido", "Reescribe para la directora: «Oye, déjanos hacer una campaña el viernes».",
    ["El destinatario es una autoridad.", "Uso registro formal y estructura de petición.", "Escribo: Estimada directora, solicitamos su autorización para realizar una campaña el viernes."],
    "Estimada directora, solicitamos su autorización para realizar una campaña el viernes."),
   ("Completar la estructura", "En un correo formal faltan estas partes: saludo, motivo, agradecimiento, despedida. ¿Cuál va primero?",
    ["Un correo se inicia saludando.", "El motivo viene después.", "El saludo va primero."],
    "El saludo")],
  [("Usar un mensaje informal con una autoridad.", "Se escribe como se habla.", "Cambia a registro formal y estructura completa."),
   ("Escribir un mensaje formal sin motivo claro.", "Se olvida la razón.", "Incluye siempre el motivo y la petición.")],
  ([E("¿Qué parte va primero en un correo formal: el saludo o la despedida?", "El saludo", "Se inicia saludando."),
    E("¿«Estimada directora» es un saludo formal?", "Sí", "Es un saludo cuidado."),
    E("¿Un mensaje formal debe tener una razón clara?", "Sí", "Explica el motivo.")],
   [E("Ordena las partes de un correo formal: motivo, despedida, saludo. ¿Cuál va en último lugar?", "La despedida", "Cierra el mensaje."),
    E("¿Qué registro conviene para un correo al director: formal o muy informal?", "Formal", "Es una autoridad."),
    E("¿Cuál es más adecuado para un grupo de amigos: «Chicos, ¿les parece si hacemos una campaña?» o «Estimados estudiantes, se solicita...»?", "Chicos, ¿les parece si hacemos una campaña?", "Hay una relación cercana.")],
   [E("¿Cuál es la mejor versión formal de «Oye, déjanos hacer una campaña el viernes»: «Estimada directora, solicitamos su autorización para realizar una campaña el viernes» o «Directora, déjenos hacer la campaña ya»?", "Estimada directora, solicitamos su autorización para realizar una campaña el viernes", "Registro formal y petición clara."),
    E("Reescribe informal: «Solicito su colaboración para ordenar la sala».", "¿Me ayudas a ordenar la sala?", "Se baja el registro."),
    E("Cambia «chao» por una despedida formal: «Saludos cordiales» o «nos vemos po».", "Saludos cordiales", "Es una despedida formal.")],
   [E("¿Por qué no basta con cambiar «tú» por «usted» para adecuar un texto?", "Porque también hay que cambiar vocabulario y estructura", "La adecuación es más que el tratamiento."),
    E("¿Cuál es una pregunta útil para adecuar un texto: «¿quién lo recibirá?» o «¿cuántas hojas me quedan?»?", "¿Quién lo recibirá?", "Define el destinatario, que orienta el registro y la estructura.")],
   [E("Un mensaje a un vecino mayor dice: «Oye, préstame la escalera». ¿Qué cambio mínimo mejora el registro?", "Usar tratamiento de usted y pedir con cortesía", "Cambia el tratamiento y el tono."),
    E("Evalúa: «Estimado director: Quiero hacer una campaña. Chao». ¿Qué le falta?", "Motivo claro, petición cortés y despedida formal", "La estructura está incompleta.")]),
  [E("Quieres pedir a la bibliotecaria que extienda el horario. ¿Cuál mensaje es más adecuado: «Oye, abre más rato» o «Estimada bibliotecaria, ¿sería posible extender el horario por una hora?»", "Estimada bibliotecaria, ¿sería posible extender el horario por una hora?", "Usa registro formal y petición cortés.")],
  [E("¿Adecuar es ajustar el texto a la situación?", "Sí", "También al propósito y destinatario."),
   E("¿Un mensaje formal tiene saludo y despedida?", "Sí", "Es parte de su estructura."),
   E("¿Se deben eliminar apodos en lo formal?", "Sí", "No corresponden a ese registro.")],
  ("Escribe dos versiones de este mensaje de ejemplo: «Quiero pedir que el curso salga 10 minutos antes el viernes para ordenar la sala para una actividad». Versión A: dirigida a la profesora jefe. Versión B: dirigida a tus compañeros por chat. Cada versión debe tener saludo, motivo, petición y despedida, con vocabulario adecuado.",
   "A: «Estimada profesora: Le escribo para solicitar que el curso salga 10 minutos antes el viernes, para ordenar la sala para una actividad. Agradezco su atención. Saludos cordiales, Camila». B: «Hola, chicos, ¿les parece salir 10 minutos antes el viernes para ordenar la sala? Gracias, nos vemos».",
   ["adecúa vocabulario y estructura", "incluye saludo, motivo, petición y despedida", "usa tratamiento coherente"], ["dos versiones"], ["usar el mismo registro en las dos", "olvidar el motivo"], "Lee las dos versiones en voz alta y comprueba que suenen distinto."),
  "Escribe un correo formal de tres líneas para pedir un favor a una persona mayor.",
  "Escribe un mensaje de despedida formal y uno informal para una misma ocasión.")

L(OA24, 4,
  MAT24,
  "Aprenderé a disentir cuidando la relación con el otro: reconocer lo válido, atenuar, usar mensajes en primera persona y proponer.",
  ["Reconozco registros.", "Sé reformular lo que dice otra persona."],
  ["Disentir es mostrar desacuerdo. No tiene por qué dañar la relación si se hace con cuidado. Hay cuatro estrategias: 1) reconocer lo válido de la idea del otro («Entiendo tu punto sobre...»); 2) atenuar el desacuerdo («Quizás tengo otra mirada», «Me parece que...»); 3) usar mensajes en primera persona («Yo veo el problema de otra manera») en vez de acusar («Estás equivocado»); 4) proponer algo («¿Y si probamos...?»).",
   "Compara: «Estás equivocado, eso no funciona» (ataca) con «Entiendo que quieres ahorrar tiempo, pero me preocupa que se pierda calidad; ¿y si probamos una versión corta?» (cuida la relación). La segunda reconoce, expresa una preocupación propia y propone. Disentir con cuidado no es ceder; es mantener la postura con respeto.",
   "Evita palabras absolutas («nunca», «siempre»), ironías, burlas o levantar la voz para ganar. Mira al otro, mantén un tono tranquilo y deja espacio para que responda. Un desacuerdo bien llevado puede terminar en una mejor idea. Y si el otro tiene razón, reconócelo: cambiar de opinión con buenos argumentos es señal de madurez."],
  [("disentir", "mostrar desacuerdo"), ("atenuar", "hacer menos fuerte lo que se dice"), ("mensaje en primera persona", "frase que expresa lo que yo pienso o siento, sin acusar"), ("reconocer lo válido", "aceptar la parte correcta de la idea del otro")],
  [("Disentir con cuidado", "Transforma «Estás equivocado» en una frase que cuide la relación.",
    ["Reconozco algo válido.", "Expreso mi mirada en primera persona.", "Escribo: Entiendo tu punto, pero yo lo veo de otra manera."],
    "Entiendo tu punto, pero yo lo veo de otra manera."),
   ("Atenuar", "¿Qué expresión atenúa más: «Eso es falso» o «Me parece que hay otro dato»?",
    ["La primera descalifica.", "La segunda deja espacio.", "Atenúa «Me parece que hay otro dato»."],
    "Me parece que hay otro dato")],
  [("Atacar a la persona en vez de discutir la idea.", "Se confunde desacuerdo con enojo.", "Habla de la idea y reconoce lo válido."),
   ("Ceder en todo para evitar el conflicto.", "Se cree que disentir es malo.", "Mantén tu postura con respeto.")],
  ([E("¿«Estás equivocado» cuida la relación o la daña?", "La daña", "Es una acusación directa."),
    E("¿«Entiendo tu punto, pero...» reconoce algo válido?", "Sí", "Reconoce la idea del otro."),
    E("¿Disentir con cuidado significa ceder siempre?", "No", "Se mantiene la postura con respeto.")],
   [E("¿Cuál atenúa más: «Eso es falso» o «Me parece que hay otro dato»?", "Me parece que hay otro dato", "Deja espacio al diálogo."),
    E("¿Qué estrategia usa «Yo veo el problema de otra manera»: mensaje en primera persona o acusación?", "Mensaje en primera persona", "Expresa lo que yo pienso."),
    E("¿Qué estrategia usa «¿Y si probamos otra forma?»: proponer o descalificar?", "Proponer", "Abre una opción.")],
   [E("¿Cuál transforma «Eso no sirve» en un desacuerdo cuidadoso: «Entiendo la idea, pero me preocupa que no resuelva el problema; ¿y si probamos otra?» o «Qué idea tan tonta»?", "Entiendo la idea, pero me preocupa que no resuelva el problema; ¿y si probamos otra?", "Reconoce, expresa preocupación y propone."),
    E("Un compañero dice «Siempre llegas tarde». ¿Qué cambio mejora la frase: reemplazar «siempre» o agregar más ejemplos?", "Reemplazar «siempre»", "Las palabras absolutas ofenden."),
    E("¿Qué parte reconoce lo válido en «Entiendo que quieres ahorrar tiempo, pero me preocupa la calidad»?", "Entiendo que quieres ahorrar tiempo", "Acepta la intención del otro.")],
   [E("Un estudiante responde con ironía: «Qué idea tan brillante...». ¿Cuida la relación?", "No", "La ironía suena a burla."),
    E("Si el otro tiene mejores argumentos, ¿qué conviene: reconocerlo o negar todo?", "Reconocerlo", "Cambiar de opinión con buenos argumentos es madurez.")],
   [E("Elige el mejor desacuerdo: «Tu idea es mala» o «Yo veo un riesgo: podría tomar demasiado tiempo; ¿cómo lo resolveríamos?»", "Yo veo un riesgo: podría tomar demasiado tiempo; ¿cómo lo resolveríamos?", "Expresa lo propio, evita acusar y propone resolver."),
    E("Evalúa: «Entiendo, pero estás equivocado». ¿Qué parte arruina la estrategia?", "Estás equivocado", "Es una acusación.")]),
  [E("En una asamblea de ejemplo, un delegado propone cerrar el patio al mediodía. Una estudiante dice: «Entiendo que quieres evitar accidentes, pero me preocupa que no tengamos dónde descansar; ¿y si cerramos solo una parte?». ¿Qué estrategias usa?", "Reconoce, expresa preocupación y propone", "Son las tres estrategias de cuidar la relación.")],
  [E("¿Disentir es mostrar desacuerdo?", "Sí", "Esa es la definición."),
   E("¿Conviene atacar a la persona al disentir?", "No", "Se discute la idea."),
   E("¿Las palabras absolutas como «nunca» o «siempre» ayudan al desacuerdo cuidadoso?", "No", "Ofenden y generalizan.")],
  ("Lee este diálogo de ejemplo. Tomás: «Propongo que el recreo se acorte a 10 minutos». Ana: «Eso es una tontería, siempre quieres lo mismo». Reescribe la respuesta de Ana en tres versiones: una con reconocimiento, una con atenuación y una con propuesta. Luego únelas en una sola respuesta cuidadosa de dos o tres frases.",
   "Reconocimiento: «Entiendo que quieres ganar tiempo de clases». Atenuación: «Me parece que 10 minutos quizás no alcancen para comer y jugar». Propuesta: «¿Y si probamos con 15 minutos un mes y revisamos?». Unida: «Entiendo que quieres ganar tiempo, pero me parece que 10 minutos quizás no alcancen; ¿y si probamos 15 un mes y revisamos?».",
   ["reconoce lo válido", "atenúa sin ceder", "propone una alternativa"], ["tres versiones y una unida"], ["atacar a la persona", "usar «siempre»"], "Lee la respuesta a otra persona y pídele que diga si se sintió respetada."),
  "Piensa en un desacuerdo reciente y escribe cómo lo dirías con las tres estrategias.",
  "Escribe un diálogo de cuatro intervenciones con un desacuerdo cuidadoso.")

L(OA24, 5,
  MAT24,
  "Aprenderé a ajustar el volumen, la velocidad y la dicción de mi voz al propósito y a la situación.",
  ["Reconozco registros y situaciones.", "Sé qué es una exposición oral."],
  ["Tu voz es una herramienta de comunicación. Tiene tres aspectos que puedes ajustar. El volumen es qué tan fuerte hablas: en una sala grande, más fuerte; en una conversación de dos, más bajo. La velocidad es qué tan rápido hablas: ni tan rápido que no te entiendan, ni tan lento que se aburran. La dicción es qué tan claramente pronuncias: cada sílaba, sin «comerte» el final de las palabras («pa» por «para», «ta» por «está»).",
   "Para ajustar tu voz, considera el propósito y la situación. Si anuncias una emergencia, hablas fuerte, claro y pausado. Si cuentas un secreto a una amiga, más suave. Si presentas ante el curso, un volumen que llegue al último banco, una velocidad media y pausas entre ideas. Las pausas ayudan a pensar y a que la audiencia asimile.",
   "Puedes entrenar tu voz: respira profundo antes de hablar, practica trabalenguas para mejorar la dicción, graba tu voz y escúchala, y practica en el lugar donde presentarás. Evita gritar, murmurar o terminar las frases con volumen bajo. Un buen uso de la voz muestra seguridad y respeto por quien escucha."],
  [("volumen", "fuerza con que se habla"), ("velocidad", "rapidez con que se habla"), ("dicción", "claridad con que se pronuncian las palabras"), ("pausa", "silencio breve entre ideas")],
  [("Ajustar el volumen", "Presentas ante el curso en una sala grande. ¿Qué volumen eliges?",
    ["Debe escucharse en el último banco.", "No tiene que ser gritado.", "Elijo un volumen alto pero cómodo."],
    "Un volumen que llegue al último banco, sin gritar"),
   ("Mejorar la dicción", "¿Cómo se pronuncia con buena dicción «pa la casa»?",
    ["Hay una palabra recortada.", "«Pa» es «para».", "Digo: para la casa."],
    "Para la casa")],
  [("Hablar muy rápido por nervios.", "No se controlan las pausas.", "Respira, haz pausas y baja la velocidad."),
   ("Bajar la voz al final de las frases.", "Se pierde energía.", "Mantén el volumen hasta terminar.")],
  ([E("¿El volumen es la fuerza con que se habla o el color de la voz?", "La fuerza con que se habla", "Es su definición."),
    E("¿La dicción se refiere a pronunciar con claridad?", "Sí", "Es su definición."),
    E("¿Hablar muy rápido ayuda a la audiencia?", "No", "No alcanzan a seguir.")],
   [E("Presentas ante el curso. ¿Qué volumen es adecuado: que llegue al último banco o uno casi inaudible?", "Que llegue al último banco", "Todos deben escuchar."),
    E("Le cuentas un secreto a una amiga. ¿Qué volumen eliges: suave o muy fuerte?", "Suave", "La situación es privada."),
    E("¿Qué ayuda a la audiencia a asimilar: las pausas o hablar sin parar?", "Las pausas", "Dan tiempo para pensar.")],
   [E("¿Cómo se dice con buena dicción «pa la casa»?", "Para la casa", "Se pronuncia completa."),
    E("¿Cómo se dice con buena dicción «ta listo»?", "Está listo", "Se pronuncian todas las sílabas."),
    E("Anuncias una emergencia en un patio. ¿Qué características debe tener tu voz: fuerte, clara y pausada o susurrante y rápida?", "Fuerte, clara y pausada", "Se necesita ser escuchado y entendido.")],
   [E("Un expositor termina las frases en voz muy baja. ¿Qué problema tiene?", "Se pierde el final de las ideas", "El volumen cae al terminar."),
    E("Un expositor habla muy rápido y se le acaba el aire. ¿Qué conviene hacer: respirar y hacer pausas o hablar aún más rápido?", "Respirar y hacer pausas", "Controla el ritmo.")],
   [E("¿Qué ejercicio ayuda a mejorar la dicción: practicar trabalenguas o gritar?", "Practicar trabalenguas", "Entrena la pronunciación."),
    E("Evalúa: un estudiante exponía con buen contenido, pero murmuraba. ¿Qué debe ajustar primero?", "El volumen y la dicción", "No lo entienden aunque el contenido sea bueno.")]),
  [E("Vas a presentar en el gimnasio, un lugar con eco y mucha gente. ¿Qué ajuste de la velocidad conviene: más lenta o más rápida?", "Más lenta", "El eco dificulta la comprensión.")],
  [E("¿Se puede entrenar la voz?", "Sí", "Con práctica, respiración y trabalenguas."),
   E("¿La velocidad y las pausas se ajustan al propósito?", "Sí", "Según la situación."),
   E("¿Gritar es una buena forma de aumentar el volumen?", "No", "Conviene proyectar la voz sin gritar.")],
  ("Tienes este texto de ejemplo para decir en voz alta: «Hoy hablaré del reciclaje de vidrio. Primero, se separa por color; luego, se tritura; finalmente, se funde para fabricar botellas nuevas». 1) Marca con una barra (/) dónde harías pausas. 2) Subraya las palabras que dirías con más énfasis. 3) Practica tres veces con volumen, velocidad y dicción y anota qué ajustaste.",
   "Pausas: «Hoy hablaré del reciclaje de vidrio. / Primero, / se separa por color; / luego, / se tritura; / finalmente, / se funde para fabricar botellas nuevas». Énfasis: vidrio, primero, luego, finalmente. Ajustes: bajar la velocidad, pronunciar «finalmente» completo, mantener el volumen al final.",
   ["marca pausas coherentes", "destaca palabras clave", "describe ajustes de voz"], ["texto marcado", "lista de ajustes"], ["no hacer pausas", "no describir ajustes"], "Pide a alguien que escuche y diga si llegó claro hasta el final."),
  "Practica un trabalenguas de tu elección tres veces, cada vez más claro.",
  "Graba un minuto de lectura y anota qué mejorarías en volumen, velocidad y dicción.")

L(OA24, 6,
  MAT24,
  "Aprenderé a evaluar el efecto que produce mi manera de hablar en la audiencia, recogiendo evidencia y ajustando mi registro, mi desacuerdo y mi voz.",
  ["Comparo oralidad y escritura.", "Uso registro, desacuerdo y voz de manera adecuada."],
  ["Evaluar el efecto es preguntarse: ¿mi manera de hablar logró lo que quería en quienes me escucharon? Para saberlo necesitas evidencia: qué dijeron los oyentes, qué entendieron, cómo reaccionaron, cuántas veces tuvieron que pedir que repitieras. No basta con tu impresión.",
   "Una pauta sencilla tiene seis criterios: 1) registro adecuado a la situación; 2) vocabulario y estructura claros; 3) desacuerdos expresados con cuidado; 4) volumen adecuado; 5) velocidad adecuada; 6) dicción clara. Cada criterio se marca como «logrado», «en desarrollo» o «por mejorar». La audiencia puede completar la pauta y escribir un comentario.",
   "Con la pauta completa, decide qué ajustar: elige uno o dos criterios en los que más puedes mejorar y define una acción concreta («practicaré pausas», «cambiaré «pa» por «para»»). Luego vuelve a hablar y compara. Evaluar es un ciclo: hablar, recoger evidencia, ajustar y hablar de nuevo."],
  [("efecto", "lo que produce en la audiencia una manera de hablar"), ("pauta", "lista de criterios para evaluar"), ("evidencia", "dato observable que respalda una evaluación"), ("ajustar", "cambiar algo para mejorarlo")],
  [("Interpretar la pauta", "En una pauta de ejemplo, seis personas marcaron «volumen: por mejorar» y dos «logrado». ¿Qué ajustar primero?",
    ["Comparo las marcas.", "Seis de ocho piden mejorar el volumen.", "Ajusto el volumen."],
    "El volumen"),
   ("Definir una acción", "Si falla la dicción, ¿qué acción concreta propones?",
    ["Debe ser observable.", "Puedo practicar trabalenguas y cambiar «pa» por «para».", "Escribo la acción."],
    "Practicar trabalenguas y pronunciar «para» completo")],
  [("Evaluar solo con la propia impresión.", "Se ignora a la audiencia.", "Recoge evidencia de quienes escucharon."),
   ("Proponer mejoras vagas.", "Se dice «hablar mejor».", "Define una acción observable.")],
  ([E("¿La evidencia sirve para evaluar el efecto?", "Sí", "Muestra cómo reaccionó la audiencia."),
    E("¿La pauta de seis criterios incluye el volumen?", "Sí", "Es el criterio 4."),
    E("¿Evaluar es un ciclo de hablar, recoger evidencia, ajustar y volver a hablar?", "Sí", "Así se mejora.")],
   [E("En una pauta de ejemplo, seis de ocho personas marcaron «volumen: por mejorar». ¿Qué conviene ajustar?", "El volumen", "Es lo que más personas señalaron."),
    E("Si la audiencia pidió dos veces que repitieras, ¿qué criterio puede fallar: dicción o registro?", "Dicción", "No pudieron entender lo dicho."),
    E("¿Qué es una pauta: una lista de criterios para evaluar o una lista de invitados?", "Una lista de criterios para evaluar", "Se marca cada criterio.")],
   [E("Resultados de ejemplo: registro, 7 «logrado»; volumen, 2 «logrado»; dicción, 5 «logrado» (de 8 personas). ¿Cuál criterio es más débil?", "Volumen", "Tiene menos «logrado»."),
    E("¿Cuál acción es concreta para mejorar el volumen: «practicar en la sala proyectando hasta el último banco» o «hablar más fuerte alguna vez»?", "Practicar en la sala proyectando hasta el último banco", "Es una acción observable."),
    E("Para mejorar la dicción, ¿qué acción es concreta: «hablar mejor» o «leer en voz alta un trabalenguas dos veces al día»?", "Leer en voz alta un trabalenguas dos veces al día", "Se puede comprobar.")],
   [E("Un estudiante dice: «Lo hice excelente porque me sentí seguro». ¿Qué evidencia falta?", "La de la audiencia", "Solo cuenta su impresión."),
    E("¿Por qué conviene elegir solo uno o dos criterios para mejorar?", "Para enfocarse en cambios que se puedan lograr", "Muchos cambios a la vez dispersan.")],
   [E("Una audiencia marcó «desacuerdo: por mejorar» tras escuchar «Eso es una tontería». ¿Qué acción propones?", "Usar reconocimiento y propuesta al disentir", "Cambia la forma de disentir."),
    E("Tras ajustar, ¿qué conviene hacer para saber si mejoró: volver a hablar y comparar o no hacer nada?", "Volver a hablar y comparar", "El ciclo se cierra con una nueva medición.")]),
  [E("En una presentación de ejemplo, de 10 personas, 8 dicen que el registro fue adecuado y 3 que se escuchó bajo el final. ¿Qué criterio ajustarías primero: registro o volumen?", "Volumen", "Es el que presenta dificultades.")],
  [E("¿La audiencia puede completar la pauta?", "Sí", "Aporta más evidencia."),
   E("¿Se deben definir acciones concretas?", "Sí", "Para poder comprobar la mejora."),
   E("¿Se evalúa solo con la impresión del expositor?", "No", "Hace falta evidencia externa.")],
  ("Imagina esta pauta de ejemplo completada por ocho personas tras tu presentación: registro 7 «logrado»; vocabulario y estructura 6 «logrado»; desacuerdo 5 «logrado»; volumen 3 «logrado»; velocidad 4 «logrado»; dicción 6 «logrado». Escribe: 1) cuál es tu criterio más fuerte y cuál el más débil; 2) dos acciones concretas de mejora; 3) cómo comprobarás si mejoraste.",
   "Más fuerte: registro (7 de 8). Más débil: volumen (3 de 8). Acciones: ensayar en el lugar de la presentación proyectando hasta el último banco; practicar pausas para bajar la velocidad. Comprobación: volver a presentar y pedir que completen la pauta; comparar cuántos marcan «logrado» en volumen y velocidad.",
   ["identifica fortaleza y debilidad con datos", "propone acciones concretas", "define cómo comprobar"], ["tres partes escritas"], ["mejoras vagas", "no comprobar la mejora"], "Comparte tu plan con otra persona y pregúntale qué acción le parece más útil."),
  "Pide a alguien que escuche un minuto de tu voz y complete la pauta de seis criterios.",
  "Diseña tu propia pauta de seis criterios para evaluar una presentación oral.")
